    byte[] tmp = new byte[8192];
    int n;
    while ((n = in.read(tmp)) != -1) {
        baos.write(tmp, 0, n);
    }
    byte[] data = baos.toByteArray();
    // Replace the existing buffer with the new data
    this.buffer = data;
    // Reset the read pointer to the beginning of the new buffer
    this.readPointer = 0;
}

